import {StringReadOnlyExpression} from "./stringExpression";
import {NumberReadOnlyExpression} from "./numberExpression";
import {MaybeReadOnlyExpression} from "./maybeExpression";
import {ConditionReadOnlyExpression} from "./conditionExpression";
import {EntityReadOnlyExpression} from "../dataExpression/Entity";

/**
 * A list-maker lambda: returns the set of blueprints (or sub-generators) the
 * generator is built over. Evaluated at generateValue()/isGeneratedBy() time so
 * the list can be produced dynamically (it can reach the live hostApi through
 * its enclosing scope).
 */
export type EntityBlueprintListMaker = () => Array<EntityBlueprintSpec | EntityGenerator>;

/**
 * A blueprint spec: a template for an entity's field maps — it carries no id
 * (the caller supplies one at registration). Any `textMap` field may be a
 * concrete value or a {@link StringGenerator}'s generateValue() grammar, so one
 * spec can denote many concrete entities. `numberMap` fields are fixed values
 * (numbers have no generator grammar).
 */
export type EntityBlueprintSpec = {
  textMap?: Record<string, StringReadOnlyExpression | string>;
  numberMap?: Record<string, NumberReadOnlyExpression | number>;
}

/**
 * EntityGenerator — a composable grammar over a set of entity blueprints. It
 * generates a random concrete entity from the union of its blueprints'
 * languages (drawn from the shared seeded LXM stream), instantiates it in the
 * world, and tests whether a given entity could have been generated by it. See
 * EntityGenerator.js.
 */
export type EntityGeneratorApi = {
  /**
   * Language = union of the blueprints' (or sub-generators') languages. Takes a
   * list-maker lambda `() => Array<blueprintSpec | subGenerator>`, evaluated at
   * generateValue()/isGeneratedBy() time so the blueprint set (and any generated
   * field values) can be produced dynamically.
   */
  oneOf: (makeList: EntityBlueprintListMaker) => EntityGenerator;

  /** Marker for HostApi surfaces */
  type: EntityGeneratorType,
}

export type EntityGeneratorType = {
  // used when declaring argument types dynamically in HostApi clients
}

export type EntityGenerator = {
  /**
   * Instantiates a new entity from a random concrete blueprint (seeded LXM),
   * registers it in the world under a fresh id, and returns a read-only
   * {@link EntityReadOnlyExpression} over it. Present (maybe.of) when the
   * language is non-empty; absent (maybe.none) for oneOf([]).
   */
  generateValue: () => MaybeReadOnlyExpression<EntityReadOnlyExpression>;

  /**
   * Exact field membership as a condition: true iff `candidate`'s field maps
   * match a member of this generator's language (id is not considered).
   */
  isGeneratedBy: (candidate: EntityReadOnlyExpression | EntityBlueprintSpec) => ConditionReadOnlyExpression<EntityReadOnlyExpression>,
}
